
<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Komercia - Plataforma de Comercio Electrónico</title>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
    <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" rel="stylesheet">
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }

        :root {
            --naranja: #FF6B00;
            --naranja-claro: #FF8C00;
            --negro: #0a0a0a;
            --negro-2: #111111;
            --negro-3: #1a1a1a;
            --gris: #888888;
            --blanco: #ffffff;
        }

        body {
            font-family: 'Inter', sans-serif;
            background: var(--negro);
            color: var(--blanco);
            overflow-x: hidden;
        }

        /* NAVBAR */
        nav {
            position: fixed;
            top: 0;
            width: 100%;
            z-index: 1000;
            padding: 20px 0;
            background: rgba(10,10,10,0.95);
            backdrop-filter: blur(10px);
            border-bottom: 1px solid rgba(255,107,0,0.1);
        }

        .nav-inner {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 30px;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 12px;
            text-decoration: none;
        }

        .logo img {
            height: 45px;
            width: auto;
        }

        .logo-text {
            font-size: 22px;
            font-weight: 800;
            color: var(--blanco);
            letter-spacing: 2px;
        }

        .logo-text span {
            color: var(--naranja);
        }

        .nav-links {
            display: flex;
            align-items: center;
            gap: 35px;
            list-style: none;
        }

        .nav-links a {
            color: #aaa;
            text-decoration: none;
            font-size: 14px;
            font-weight: 500;
            transition: color 0.3s;
        }

        .nav-links a:hover { color: var(--naranja); }

        .btn-nav {
            background: var(--naranja);
            color: var(--blanco);
            padding: 10px 24px;
            border-radius: 8px;
            font-weight: 600;
            font-size: 14px;
            text-decoration: none;
            transition: all 0.3s;
        }

        .btn-nav:hover {
            background: var(--naranja-claro);
            transform: translateY(-1px);
            color: var(--blanco);
        }

        /* HERO */
        .hero {
            min-height: 100vh;
            display: flex;
            align-items: center;
            position: relative;
            padding: 120px 30px 80px;
            overflow: hidden;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: -200px;
            right: -200px;
            width: 600px;
            height: 600px;
            background: radial-gradient(circle, rgba(255,107,0,0.15) 0%, transparent 70%);
            pointer-events: none;
        }

        .hero::after {
            content: '';
            position: absolute;
            bottom: -100px;
            left: -100px;
            width: 400px;
            height: 400px;
            background: radial-gradient(circle, rgba(255,107,0,0.08) 0%, transparent 70%);
            pointer-events: none;
        }

        .hero-inner {
            max-width: 1200px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 60px;
            align-items: center;
        }

        .hero-badge {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            background: rgba(255,107,0,0.1);
            border: 1px solid rgba(255,107,0,0.3);
            color: var(--naranja);
            padding: 8px 16px;
            border-radius: 50px;
            font-size: 13px;
            font-weight: 600;
            margin-bottom: 24px;
        }

        .hero-badge i { font-size: 11px; }

        .hero h1 {
            font-size: 58px;
            font-weight: 900;
            line-height: 1.1;
            margin-bottom: 24px;
            letter-spacing: -1px;
        }

        .hero h1 span {
            color: var(--naranja);
            position: relative;
        }

        .hero p {
            font-size: 18px;
            color: #aaa;
            line-height: 1.7;
            margin-bottom: 40px;
            max-width: 480px;
        }

        .hero-btns {
            display: flex;
            gap: 16px;
            flex-wrap: wrap;
        }

        .btn-primary {
            background: var(--naranja);
            color: var(--blanco);
            padding: 16px 32px;
            border-radius: 10px;
            font-weight: 700;
            font-size: 16px;
            text-decoration: none;
            transition: all 0.3s;
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .btn-primary:hover {
            background: var(--naranja-claro);
            transform: translateY(-2px);
            box-shadow: 0 10px 30px rgba(255,107,0,0.3);
            color: var(--blanco);
        }

        .btn-secondary {
            background: transparent;
            color: var(--blanco);
            padding: 16px 32px;
            border-radius: 10px;
            font-weight: 600;
            font-size: 16px;
            text-decoration: none;
            border: 1px solid rgba(255,255,255,0.2);
            transition: all 0.3s;
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .btn-secondary:hover {
            border-color: var(--naranja);
            color: var(--naranja);
        }

        .hero-stats {
            display: flex;
            gap: 40px;
            margin-top: 50px;
            padding-top: 40px;
            border-top: 1px solid rgba(255,255,255,0.08);
        }

        .stat h3 {
            font-size: 32px;
            font-weight: 800;
            color: var(--naranja);
        }

        .stat p {
            font-size: 13px;
            color: #666;
            margin: 0;
        }

        /* HERO VISUAL */
        .hero-visual {
            position: relative;
        }

        .dashboard-mockup {
            background: var(--negro-3);
            border: 1px solid rgba(255,107,0,0.2);
            border-radius: 16px;
            overflow: hidden;
            box-shadow: 0 40px 80px rgba(0,0,0,0.5), 0 0 0 1px rgba(255,107,0,0.1);
        }

        .mockup-header {
            background: var(--negro-2);
            padding: 14px 20px;
            display: flex;
            align-items: center;
            gap: 8px;
            border-bottom: 1px solid rgba(255,255,255,0.05);
        }

        .mockup-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
        }

        .mockup-dot:nth-child(1) { background: #ff5f57; }
        .mockup-dot:nth-child(2) { background: #febc2e; }
        .mockup-dot:nth-child(3) { background: #28c840; }

        .mockup-url {
            background: rgba(255,255,255,0.05);
            border-radius: 6px;
            padding: 4px 12px;
            font-size: 11px;
            color: #666;
            margin-left: 10px;
            flex: 1;
            text-align: center;
        }

        .mockup-body {
            padding: 24px;
        }

        .mockup-greeting {
            font-size: 13px;
            color: #666;
            margin-bottom: 4px;
        }

        .mockup-title {
            font-size: 20px;
            font-weight: 700;
            margin-bottom: 20px;
        }

        .mockup-cards {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 12px;
            margin-bottom: 20px;
        }

        .mockup-card {
            background: var(--negro-2);
            border-radius: 10px;
            padding: 16px;
            border: 1px solid rgba(255,255,255,0.05);
        }

        .mockup-card-label {
            font-size: 11px;
            color: #666;
            margin-bottom: 6px;
        }

        .mockup-card-value {
            font-size: 22px;
            font-weight: 700;
            color: var(--naranja);
        }

        .mockup-card-change {
            font-size: 10px;
            color: #28c840;
            margin-top: 2px;
        }

        .mockup-products {
            background: var(--negro-2);
            border-radius: 10px;
            padding: 16px;
            border: 1px solid rgba(255,255,255,0.05);
        }

        .mockup-products-title {
            font-size: 12px;
            font-weight: 600;
            margin-bottom: 12px;
            color: #aaa;
        }

        .mockup-product-row {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 8px 0;
            border-bottom: 1px solid rgba(255,255,255,0.03);
        }

        .mockup-product-row:last-child { border-bottom: none; }

        .mockup-product-img {
            width: 32px;
            height: 32px;
            background: rgba(255,107,0,0.2);
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
        }

        .mockup-product-name {
            font-size: 11px;
            flex: 1;
        }

        .mockup-product-price {
            font-size: 11px;
            color: var(--naranja);
            font-weight: 600;
        }

        /* FLOATING BADGES */
        .float-badge {
            position: absolute;
            background: var(--negro-2);
            border: 1px solid rgba(255,107,0,0.3);
            border-radius: 12px;
            padding: 12px 16px;
            display: flex;
            align-items: center;
            gap: 10px;
            font-size: 12px;
            font-weight: 600;
            box-shadow: 0 10px 30px rgba(0,0,0,0.4);
            animation: float 3s ease-in-out infinite;
        }

        .float-badge-1 {
            top: -20px;
            right: -20px;
            animation-delay: 0s;
        }

        .float-badge-2 {
            bottom: 40px;
            left: -30px;
            animation-delay: 1.5s;
        }

        .float-badge i {
            color: var(--naranja);
            font-size: 16px;
        }

        @keyframes float {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-8px); }
        }

        /* COMO FUNCIONA */
        .section {
            padding: 100px 30px;
        }

        .section-inner {
            max-width: 1200px;
            margin: 0 auto;
        }

        .section-label {
            color: var(--naranja);
            font-size: 13px;
            font-weight: 600;
            letter-spacing: 2px;
            text-transform: uppercase;
            margin-bottom: 12px;
        }

        .section-title {
            font-size: 42px;
            font-weight: 800;
            margin-bottom: 16px;
            letter-spacing: -0.5px;
        }

        .section-subtitle {
            font-size: 18px;
            color: #777;
            max-width: 500px;
            line-height: 1.6;
            margin-bottom: 60px;
        }

        /* STEPS */
        .steps {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 30px;
        }

        .step {
            background: var(--negro-3);
            border: 1px solid rgba(255,255,255,0.06);
            border-radius: 16px;
            padding: 36px 30px;
            position: relative;
            transition: all 0.3s;
        }

        .step:hover {
            border-color: rgba(255,107,0,0.3);
            transform: translateY(-4px);
        }

        .step-number {
            width: 48px;
            height: 48px;
            background: rgba(255,107,0,0.15);
            border: 1px solid rgba(255,107,0,0.3);
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
            font-weight: 800;
            color: var(--naranja);
            margin-bottom: 20px;
        }

        .step h3 {
            font-size: 20px;
            font-weight: 700;
            margin-bottom: 12px;
        }

        .step p {
            font-size: 15px;
            color: #777;
            line-height: 1.6;
        }

        /* FEATURES */
        .features-bg {
            background: var(--negro-2);
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
        }

        .feature {
            padding: 30px;
            border-radius: 16px;
            border: 1px solid rgba(255,255,255,0.06);
            background: var(--negro-3);
            transition: all 0.3s;
        }

        .feature:hover {
            border-color: rgba(255,107,0,0.2);
            transform: translateY(-3px);
        }

        .feature-icon {
            width: 52px;
            height: 52px;
            background: rgba(255,107,0,0.1);
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 20px;
            font-size: 22px;
            color: var(--naranja);
        }

        .feature h3 {
            font-size: 18px;
            font-weight: 700;
            margin-bottom: 10px;
        }

        .feature p {
            font-size: 14px;
            color: #666;
            line-height: 1.6;
        }

        /* PRICING */
        .pricing-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
            align-items: center;
        }

        .pricing-card {
            background: var(--negro-3);
            border: 1px solid rgba(255,255,255,0.06);
            border-radius: 20px;
            padding: 40px 30px;
            text-align: center;
            transition: all 0.3s;
        }

        .pricing-card.featured {
            background: linear-gradient(135deg, rgba(255,107,0,0.15), rgba(255,140,0,0.05));
            border-color: var(--naranja);
            transform: scale(1.05);
            position: relative;
        }

        .pricing-badge {
            position: absolute;
            top: -14px;
            left: 50%;
            transform: translateX(-50%);
            background: var(--naranja);
            color: white;
            padding: 4px 16px;
            border-radius: 50px;
            font-size: 12px;
            font-weight: 700;
            white-space: nowrap;
        }

        .pricing-plan {
            font-size: 13px;
            color: #666;
            font-weight: 600;
            letter-spacing: 1px;
            text-transform: uppercase;
            margin-bottom: 12px;
        }

        .pricing-price {
            font-size: 48px;
            font-weight: 900;
            color: var(--blanco);
            margin-bottom: 4px;
        }

        .pricing-price span {
            font-size: 18px;
            color: #666;
            font-weight: 400;
        }

        .pricing-desc {
            font-size: 14px;
            color: #666;
            margin-bottom: 30px;
        }

        .pricing-features {
            list-style: none;
            margin-bottom: 30px;
            text-align: left;
        }

        .pricing-features li {
            padding: 8px 0;
            font-size: 14px;
            color: #aaa;
            display: flex;
            align-items: center;
            gap: 10px;
            border-bottom: 1px solid rgba(255,255,255,0.04);
        }

        .pricing-features li i {
            color: var(--naranja);
            font-size: 12px;
        }

        .btn-pricing {
            display: block;
            padding: 14px;
            border-radius: 10px;
            font-weight: 700;
            font-size: 15px;
            text-decoration: none;
            transition: all 0.3s;
        }

        .btn-pricing-outline {
            border: 1px solid rgba(255,255,255,0.15);
            color: var(--blanco);
        }

        .btn-pricing-outline:hover {
            border-color: var(--naranja);
            color: var(--naranja);
        }

        .btn-pricing-filled {
            background: var(--naranja);
            color: var(--blanco);
        }

        .btn-pricing-filled:hover {
            background: var(--naranja-claro);
            box-shadow: 0 8px 25px rgba(255,107,0,0.3);
            color: var(--blanco);
        }

        /* CTA FINAL */
        .cta-section {
            padding: 100px 30px;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .cta-section::before {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 600px;
            height: 600px;
            background: radial-gradient(circle, rgba(255,107,0,0.12) 0%, transparent 70%);
            pointer-events: none;
        }

        .cta-section h2 {
            font-size: 52px;
            font-weight: 900;
            margin-bottom: 20px;
            letter-spacing: -1px;
        }

        .cta-section p {
            font-size: 18px;
            color: #777;
            margin-bottom: 40px;
        }

        /* FOOTER */
        footer {
            background: var(--negro-2);
            border-top: 1px solid rgba(255,255,255,0.05);
            padding: 60px 30px 30px;
        }

        .footer-inner {
            max-width: 1200px;
            margin: 0 auto;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 40px;
            margin-bottom: 50px;
        }

        .footer-brand p {
            font-size: 14px;
            color: #555;
            line-height: 1.7;
            margin-top: 16px;
            max-width: 280px;
        }

        .footer-col h4 {
            font-size: 13px;
            font-weight: 700;
            color: #aaa;
            letter-spacing: 1px;
            text-transform: uppercase;
            margin-bottom: 20px;
        }

        .footer-col ul {
            list-style: none;
        }

        .footer-col ul li {
            margin-bottom: 10px;
        }

        .footer-col ul li a {
            color: #555;
            text-decoration: none;
            font-size: 14px;
            transition: color 0.3s;
        }

        .footer-col ul li a:hover { color: var(--naranja); }

        .footer-bottom {
            padding-top: 30px;
            border-top: 1px solid rgba(255,255,255,0.05);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .footer-bottom p {
            font-size: 13px;
            color: #444;
        }

        .footer-bottom span { color: var(--naranja); }

        .social-links {
            display: flex;
            gap: 12px;
        }

        .social-links a {
            width: 36px;
            height: 36px;
            background: rgba(255,255,255,0.05);
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #555;
            text-decoration: none;
            font-size: 14px;
            transition: all 0.3s;
        }

        .social-links a:hover {
            background: var(--naranja);
            color: var(--blanco);
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
            .hero-inner { grid-template-columns: 1fr; }
            .hero-visual { display: none; }
            .hero h1 { font-size: 40px; }
            .steps { grid-template-columns: 1fr; }
            .features-grid { grid-template-columns: 1fr 1fr; }
            .pricing-grid { grid-template-columns: 1fr; }
            .pricing-card.featured { transform: none; }
            .footer-grid { grid-template-columns: 1fr 1fr; }
            .nav-links { display: none; }
        }
    </style>
</head>
<body>

    <!-- NAVBAR -->
    <nav>
        <div class="nav-inner">
            <a href="/" class="logo">
                <img src="data:image/png;base64," alt="Komercia" style="height:50px;width:auto;">
            </a>
            <ul class="nav-links">
                <li><a href="#como-funciona">Cómo funciona</a></li>
                <li><a href="#caracteristicas">Características</a></li>
                <li><a href="#precios">Precios</a></li>
                <li><a href="/login">Iniciar sesión</a></li>
            </ul>
            <a href="/registro" class="btn-nav">Crear tienda gratis →</a>
        </div>
    </nav>

    <!-- HERO -->
    <section class="hero">
        <div class="hero-inner">
            <div class="hero-content">
                <div class="hero-badge">
                    <i class="fas fa-bolt"></i>
                    Crea tu tienda en minutos, no en semanas
                </div>
                <h1>Tu tienda online <span>lista para vender</span> hoy mismo</h1>
                <p>Komercia es la plataforma más fácil de LATAM para que cualquier comerciante tenga su tienda virtual profesional sin necesidad de conocimientos técnicos.</p>
                <div class="hero-btns">
                    <a href="/registro" class="btn-primary">
                        <i class="fas fa-store"></i>
                        Crear mi tienda gratis
                    </a>
                    <a href="#como-funciona" class="btn-secondary">
                        <i class="fas fa-play-circle"></i>
                        Ver cómo funciona
                    </a>
                </div>
                <div class="hero-stats">
                    <div class="stat">
                        <h3>3 min</h3>
                        <p>Para tener tu tienda lista</p>
                    </div>
                    <div class="stat">
                        <h3>0</h3>
                        <p>Conocimientos técnicos</p>
                    </div>
                    <div class="stat">
                        <h3>100%</h3>
                        <p>Tuya y personalizable</p>
                    </div>
                </div>
            </div>

            <div class="hero-visual">
                <div class="float-badge float-badge-1">
                    <i class="fas fa-check-circle"></i>
                    <div>
                        <div style="font-size:11px;color:#aaa">Nueva venta</div>
                        <div>+ S/. 250.00</div>
                    </div>
                </div>
                <div class="dashboard-mockup">
                    <div class="mockup-header">
                        <div class="mockup-dot"></div>
                        <div class="mockup-dot"></div>
                        <div class="mockup-dot"></div>
                        <div class="mockup-url">komercia.online/mitienda</div>
                    </div>
                    <div class="mockup-body">
                        <div class="mockup-greeting">Bienvenido de vuelta 👋</div>
                        <div class="mockup-title">Mi Panel de Ventas</div>
                        <div class="mockup-cards">
                            <div class="mockup-card">
                                <div class="mockup-card-label">Ventas hoy</div>
                                <div class="mockup-card-value">S/. 1,240</div>
                                <div class="mockup-card-change">↑ +18% vs ayer</div>
                            </div>
                            <div class="mockup-card">
                                <div class="mockup-card-label">Pedidos</div>
                                <div class="mockup-card-value">24</div>
                                <div class="mockup-card-change">↑ +5 nuevos</div>
                            </div>
                        </div>
                        <div class="mockup-products">
                            <div class="mockup-products-title">MIS PRODUCTOS</div>
                            <div class="mockup-product-row">
                                <div class="mockup-product-img">👟</div>
                                <div class="mockup-product-name">Zapatillas deportivas</div>
                                <div class="mockup-product-price">S/. 180</div>
                            </div>
                            <div class="mockup-product-row">
                                <div class="mockup-product-img">👗</div>
                                <div class="mockup-product-name">Vestido floral</div>
                                <div class="mockup-product-price">S/. 95</div>
                            </div>
                            <div class="mockup-product-row">
                                <div class="mockup-product-img">👜</div>
